import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        t = float(data)
    except ValueError:
        return

    if t < 0:
        result = "Freezing"
    elif t <= 20:
        result = "Cold"
    elif t <= 30:
        result = "Moderate"
    else:
        result = "Hot"

    print(result)

if __name__ == "__main__":
    main()
